/** SVG 아이콘 (모노크롬) — id, label, svg path */
export interface IconEntry {
  id: string;
  label: string;
  /** SVG path d attribute (24x24 viewBox) — 단일 path 아이콘 */
  path?: string;
  /** inner SVG markup (circle/line/rect 등 포함 가능) — path 대신 사용 (lucide 추출) */
  svg?: string;
  /** 검색 키워드 (한/영) */
  kw?: string;
}

/** IconEntry 의 inner SVG 마크업 (svg 우선, 없으면 path) — 모든 렌더러 공통 */
export function iconSvgInner(ic: IconEntry): string {
  return ic.svg ?? (ic.path ? `<path d="${ic.path}"/>` : "");
}

export interface IconCategory {
  id: string;
  label: LocalizedText;
  icons: IconEntry[];
}

